with_agent.content:
这是一个典型的 UI 增强需求，目标是：**在不干扰输入流的前提下，为聊天输入框（`<textarea>` 或 `contenteditable`）提供一个轻量、可悬停展开的「关联项目」快捷入口**。

下面给出一个 **生产就绪、最小侵入、可复用** 的 React + TypeScript 组件方案，基于现代 CSS-in-JS（使用 `styled-components` 或原生 `className`），支持：

- 悬停展开（无点击、无遮挡、无焦点丢失）
- 项目列表动态加载（预留接口）
- 键盘友好（Tab 可聚焦，Enter 可选中）
- 无障碍（ARIA 标签、role、focus management）
- 零副作用（不劫持输入框 focus/blur，不修改原有事件流）

---

### ✅ 方案概览

```
ChatInputWithProjectPicker
├── ChatInput (原输入框，保持不变)
└── ProjectPickerTrigger (悬浮按钮 → 悬停展开菜单)
    └── ProjectMenu (绝对定位浮层，含项目列表 + 搜索 + 选择逻辑)
```

---

### 📄 完整实现（React + TypeScript）

```tsx
// ChatInputWithProjectPicker.tsx
import React, { useState, useRef, useEffect, useCallback } from 'react';
import './ChatInputWithProjectPicker.css'; // 可选：CSS Module 或 styled-components

interface Project {
  id: string;
  name: string;
  path?: string;
  icon?: string;
}

interface ChatInputWithProjectPickerProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: () => void;
  // 可选：外部传入项目列表（或留空由内部 mock/fetch）
  projects?: Project[];
  onProjectSelect?: (project: Project) => void;
  placeholder?: string;
}

export const ChatInputWithProjectPicker: React.FC<ChatInputWithProjectPickerProps> = ({
  value,
  onChange,
  onSubmit,
  projects = [],
  onProjectSelect,
  placeholder = '输入消息...',
}) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  // 过滤项目（支持模糊匹配）
  const filteredProjects = projects.filter((p) =>
    p.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // 点击外部关闭菜单
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        menuRef.current &&
        !menuRef.current.contains(e.target as Node) &&
        triggerRef.current &&
        !triggerRef.current.contains(e.target as Node)
      ) {
        setIsMenuOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 键盘导航支持（Tab / ArrowDown / Enter）
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (!isMenuOpen || e.key !== 'Enter') return;
      const firstItem = menuRef.current?.querySelector('button[role="option"]');
      firstItem?.click();
    },
    [isMenuOpen]
  );

  useEffect(() => {
    if (isMenuOpen) {
      document.addEventListener('keydown', handleKeyDown);
      return () => document.removeEventListener('keydown', handleKeyDown);
    }
  }, [isMenuOpen, handleKeyDown]);

  const handleSelect = (project: Project) => {
    setIsMenuOpen(false);
    onProjectSelect?.(project);
  };

  return (
    <div className="chat-input-with-project-picker">
      <div className="chat-input-wrapper">
        <textarea
          className="chat-input"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              onSubmit();
            }
          }}
          placeholder={placeholder}
          rows={1}
          style={{ resize: 'none', overflow: 'hidden' }}
        />
        <button
          ref={triggerRef}
          type="button"
          className="project-trigger"
          aria-haspopup="listbox"
          aria-expanded={isMenuOpen}
          aria-label="关联项目"
          onMouseEnter={() => setIsMenuOpen(true)}
          onFocus={() => setIsMenuOpen(true)}
        >
          📁
        </button>
      </div>

      {isMenuOpen && (
        <div
          ref={menuRef}
          className="project-menu"
          role="listbox"
          aria-label="项目列表"
        >
          <div className="project-search">
            <input
              type="text"
              placeholder="搜索项目..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              autoFocus
              aria-label="搜索项目"
            />
          </div>
          <div className="project-list">
            {filteredProjects.length === 0 ? (
              <div className="project-empty">暂无匹配项目</div>
            ) : (
              filteredProjects.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  role="option"
                  className="project-item"
                  onClick={() => handleSelect(p)}
                  aria-label={`选择项目 ${p.name}`}
                >
                  {p.icon && <span className="project-icon">{p.icon}</span>}
                  <span className="project-name">{p.name}</span>
                </button>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
};
```

