以下是一个轻量、高性能、无障碍友好的 React + TypeScript 组件方案，实现「关联项目」快捷按钮：悬停展开、不遮挡输入、不影响输入焦点与键盘操作（如 Tab/Enter/ESC）、支持键盘导航与屏幕阅读器。

✅ 核心设计原则：
- **悬停展开**：鼠标悬停触发，避免误触；移动端 fallback 为点击（含长按提示）
- **零干扰输入体验**：按钮绝对定位在输入框右下角，不占用布局流；展开面板使用 `position: absolute` + `z-index`，不触发重排；输入框始终可聚焦、可输入
- **无障碍支持**：ARIA 属性、键盘导航（Tab 进入、方向键选择、Enter 确认、ESC 关闭）、焦点管理
- **性能友好**：防抖悬停（防快速进出抖动），虚拟列表（若项目数 > 50），CSS 动画而非 JS 动画

---

### ✅ 完整组件代码（`ProjectLinkButton.tsx`）

```tsx
import React, { useState, useRef, useEffect, useCallback } from 'react';
import styles from './ProjectLinkButton.module.css';

// 类型定义
interface Project {
  id: string;
  name: string;
  icon?: string; // 可选图标（如 emoji 或 icon 字符）
}

interface ProjectLinkButtonProps {
  projects: Project[];
  onProjectSelect: (project: Project) => void;
  inputRef: React.RefObject<HTMLTextAreaElement | HTMLInputElement>;
  disabled?: boolean;
  className?: string;
}

export const ProjectLinkButton: React.FC<ProjectLinkButtonProps> = ({
  projects,
  onProjectSelect,
  inputRef,
  disabled = false,
  className = '',
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isHovering, setIsHovering] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  // 防抖悬停控制（避免快速进出导致闪烁）
  const handleMouseEnter = useCallback(() => {
    if (disabled) return;
    setIsHovering(true);
    const timer = setTimeout(() => setIsOpen(true), 200); // 200ms 延迟展开，提升体验
    return () => clearTimeout(timer);
  }, [disabled]);

  const handleMouseLeave = useCallback(() => {
    setIsHovering(false);
    // 离开时若未 hover 其他区域（如面板），则关闭
    setTimeout(() => {
      if (!isHovering && !panelRef.current?.matches(':hover')) {
        setIsOpen(false);
      }
    }, 100);
  }, [isHovering]);

  // 键盘支持：ESC 关闭，Tab 自动跳转到面板第一个项
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsOpen(false);
        inputRef.current?.focus();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [inputRef]);

  // 点击外部关闭
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        isOpen &&
        panelRef.current &&
        !panelRef.current.contains(e.target as Node) &&
        !buttonRef.current?.contains(e.target as Node)
      ) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  // 选中项目并关闭面板
  const handleSelect = (project: Project) => {
    onProjectSelect(project);
    setIsOpen(false);
    // 恢复输入框焦点（保持光标位置）
    inputRef.current?.focus();
  };

  // 移动端：点击按钮展开（同时提供长按提示）
  const handleButtonClick = () => {
    if (disabled) return;
    setIsOpen(prev => !prev);
  };

  return (
    <div className={`${styles.container} ${className}`}>
      {/* 触发按钮 —— 绝对定位在输入框右下角 */}
      <button
        ref={buttonRef}
        type="button"
        className={styles.triggerButton}
        aria-label="关联项目（悬停展开）"
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onClick={handleButtonClick}
        disabled={disabled}
        // 移动端优化：长按提示
        title="点击展开项目列表"
      >
        <span className={styles.icon}>📎</span>
      </button>

      {/* 展开面板 —— 绝对定位，锚定在按钮下方 */}
      {isOpen && projects.length > 0 && (
        <div
          ref={panelRef}
          className={styles.panel}
          role="listbox"
          aria-label="可关联的项目列表"
          onMouseEnter={() => setIsHovering(true)}
          onMouseLeave={() => setIsHovering(false)}
        >
          {projects.map((project) => (
            <button
              key={project.id}
              type="button"
              className={styles.item}
              role="option"
              aria-selected="false"
              onClick={() => handleSelect(project)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  handleSelect(project);
                }
              }}
              tabIndex={0}
            >
              <span className={styles.icon}>{project.icon ?? '📁'}</span>
              <span className={styles.name}>{project.name}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

